//! `sectormanager`: per-level sector-clipping set-up object (`Game Logic Modules/Globals/SectorClipping/
//! sectormanager__*/SectorManager.c`, 7 functions). Finds the start sector from the floor under the
//! respawn object, hands the level's sector map to ApiSectorClipping, then calls ApiImpl_Update with the
//! sector of the floor attribute in game buffer 0 +100 every frame.
//!
//! All 27 builds (per-build data in sectormanager_builds.rs, generated by
//! tools/rustport/gen_sectormanager.py). EP4 variants: GetFloorAttrib (2d3b4cb9, 69c1a701, ecffc865:
//! the states re-cast the hero 0x2a00000d floor ray every frame and write GB0+100 themselves) and
//! TransparentObjBuff (829d9103, e57f867b: first frame sets up transparent objects). Every EP1 build has ui32FlagSectorClipping = 1: sector clipping off, the object
//! kills itself in its constructor (after writing GB0+100) and ApiSectorClipping is a no-op.
#![allow(non_snake_case, non_upper_case_globals, unused_variables)]
use super::sectormanager_builds::{BUILDS, IMAGE_SIZE};
use crate::engine::*;
use crate::libs::api_sector_clipping as clip;
use crate::logic::{CodeFn, LResult, ModuleDef};

#[derive(Debug)]
pub struct Build {
    pub key: &'static str,
    /// respawn object the start floor ray is cast from
    pub respawn: u32,
    pub mask: u32,
    pub shift: u32,
    pub count: u32,
    /// aaSectorMap
    pub map: u32,
    pub msg_in: u32,
    pub msg_out: u32,
    /// $f12 of ApiImpl_Initialize (fade time, f32 bits)
    pub fade: u32,
    /// ui32FlagSectorClipping
    pub flag: u32,
    /// pGameData
    pub game_data: u32,
    /// GetFloorAttrib variant
    pub floor: bool,
    /// TransparentObjBuff (0 = none) and its record count (0x14-byte records)
    pub transp: u32,
    pub transp_n: u32,
    /// .data image 0x10000..=flag: word count (the words are read from the disc image, WP-X1)
    pub data: u32,
    /// word indices of `data` holding module addresses (R_MIPS_32)
    pub relocs: &'static [usize],
}

pub static MODULE: ModuleDef = ModuleDef {
    name: "sectormanager",
    data_size: IMAGE_SIZE + 4,
    ctor: sectormanagerConstructor,
    dtor: sectormanagerDestructor,
    register: None,
    init: &[],
    build_init: Some(build_init),
};

pub fn build_index(key: &str) -> Option<usize> {
    BUILDS.iter().position(|b| b.key == key)
}

fn build_init(m: &mut Mem, data: Ptr, build: usize) {
    let b = &BUILDS[build];
    for (i, &w) in crate::engine::gamedata::words(b.key, 0x10000, b.data).iter().enumerate() {
        let v = if b.relocs.contains(&i) { data + w } else { w };
        m.w32(data + i as u32 * 4, v);
    }
    m.w32(data + IMAGE_SIZE, 0);
}

fn B(e: &Engine) -> &'static Build {
    &BUILDS[e.rt.cur_build()]
}
fn G(e: &Engine, a: u32) -> Ptr {
    e.rt.cur_data() + (a - 0x10000)
}
fn game_data(e: &Engine) -> Ptr {
    e.r32(G(e, B(e).game_data))
}
fn sector(e: &Engine) -> u16 {
    let b = B(e);
    ((e.r32(game_data(e) + 100) & b.mask) >> b.shift) as u16
}

const SELF: u32 = 0x2a00_0000;

/// 0x00010d50
/// quirk/port: ApiSectorClipping calls this through its pointer from the CLIENT's module context
/// (gramophone, carts...), where `B(e)` would be the caller's build. The original reads its own
/// module's globals, so look up the (single) loaded sectormanager code instead.
fn SectorExtractor(e: &mut Engine, a: u32) -> u32 {
    let b = &BUILDS[e.rt.codes.iter().find(|c| std::ptr::eq(c.def, &MODULE)).expect("sectormanager not loaded").build];
    (a & b.mask) >> b.shift
}

/// `static ui32FloorAttrib` of GetFloorAttrib (kept past the image)
fn floor_static(e: &Engine) -> Ptr {
    e.rt.cur_data() + IMAGE_SIZE
}

/// GetFloorAttrib (EP4 variants): floor attribute under the hero 0x2a00000d (ray from +0.5 m down 1 m),
/// last hit kept when the ray misses
fn GetFloorAttrib(e: &mut Engine) -> u32 {
    let ray = e.alloca(0x40);
    let out = e.alloca(0x60);
    APIgameobj::GetPosition(e, 0x2a00_000d, 0x7fff_ffff, ray);
    let y = e.rf(ray + 4) + 0.5;
    e.wf(ray + 4, y);
    e.wf(ray + 0x10, -1.0);
    e.w32(ray + 0x20, 0);
    e.w32(ray + 0x24, B(e).mask);
    if APIphysic::CheckRayIntersection(e, ray, out) == 2 {
        let v = e.r32(out + 0x24);
        let a = floor_static(e);
        e.w32(a, v);
    }
    e.r32(floor_static(e))
}

/// 0x00010d90
pub fn SectorManager_InitializeSectorClipping(e: &mut Engine) -> LResult<()> {
    let b = B(e);
    let ray = e.alloca(0x40);
    let out = e.alloca(0x60);
    APIgameobj::GetPosition(e, b.respawn, 0x7fff_ffff, ray);
    let y = e.rf(ray + 4) + 1.0;
    e.wf(ray + 4, y);
    e.wf(ray + 0x10, -11.0);
    e.w32(ray + 0x20, 8);
    e.w32(ray + 0x24, b.mask);
    let r = APIphysic::CheckRayIntersection(e, ray, out);
    let s = e.cstr("sectormanagerConstructor - Initial respawn point is not over floor");
    APIextra::Assert(e, (r == 2) as u32, s);
    let gd = game_data(e);
    let v = e.r32(out + 0x24);
    e.w32(gd + 100, v);
    let flag = e.r32(G(e, b.flag));
    let x = e.code_ptr(CodeFn::Word(SectorExtractor));
    let map = G(e, b.map);
    let cur = sector(e);
    clip::ApiImpl_Initialize(e, f32::from_bits(b.fade), map, b.count, cur, x, b.msg_in, b.msg_out, flag);
    if flag == 1 {
        APIgameobj::KillObject(e, SELF);
    }
    Ok(())
}

/// 0x00010f10
pub fn sectormanagerConstructor(e: &mut Engine, api: Ptr, instanceCount: i32) -> LResult<()> {
    if instanceCount == 1 {
        APIcons::SetExternalFunction(e, 0, sectormanagerST_FIRST_FRAME);
        APIcons::SetExternalFunction(e, 1, sectormanagerST_BASICMOVE);
        let v = APIgameobj::GetGameBuffer(e, 0, 0x8f8, 1);
        let a = G(e, B(e).game_data);
        e.w32(a, v);
    }
    SectorManager_InitializeSectorClipping(e)?;
    LIBMiscFunc::MiscFunc_ChangeClipping(e, SELF, 2, NULL, 0);
    APIcons::SetInitialState(e, 0);
    Ok(())
}

/// 0x000110b8
pub fn sectormanagerDestructor(e: &mut Engine, instanceCount: i32) -> LResult<()> {
    if instanceCount == 0 {
        APIgameobj::FreeGameBuffer(e, 0);
    }
    Ok(())
}

/// 0x00011108
pub fn sectormanagerST_FIRST_FRAME(e: &mut Engine, _: u32) -> LResult<u64> {
    let b = B(e);
    if b.floor {
        let v = GetFloorAttrib(e);
        let gd = game_data(e);
        e.w32(gd + 100, v);
    }
    for i in 0..b.transp_n {
        let r = G(e, b.transp) + i * 0x14;
        let id = e.r32(r);
        APIgameobj::SendMessageTo(e, id, NULL, 0x203, 0, r);
        let p = e.r32(r + 0xc);
        APIgameobj::SetTransparentPriority(e, id, 0, p);
        if e.r32(r + 8) != 0 {
            APIanim::Play(e, id, 1, 2, 0.0);
        }
        let v = e.alloca(0x10);
        APIgameobj::GetPosition(e, id, 0x7fff_ffff, v);
        let y = e.rf(v + 4) - e.rf(r + 0x10);
        e.wf(v + 4, y);
        APIgameobj::SetTranslation(e, id, v);
    }
    let s = sector(e);
    clip::ApiImpl_Update(e, s);
    APIgameobj::SetNextState(e, SELF, 1);
    Ok(0)
}

/// 0x00011190
pub fn sectormanagerST_BASICMOVE(e: &mut Engine, _: u32) -> LResult<u64> {
    if B(e).floor {
        let v = GetFloorAttrib(e);
        let gd = game_data(e);
        e.w32(gd + 100, v);
    }
    let s = sector(e);
    clip::ApiImpl_Update(e, s);
    Ok(0)
}
